import{_ as t,a,c as r,ac as n}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"结构型设计模式","description":"先判断要转换接口、简化入口、叠加行为、控制访问，还是组合对象结构；再决定是否需要桥接独立维度或共享不可变状态。","frontmatter":{"title":"结构型设计模式","description":"先判断要转换接口、简化入口、叠加行为、控制访问，还是组合对象结构；再决定是否需要桥接独立维度或共享不可变状态。","generated":"consolidation-v2","showdocs":{"topics":[{"id":"patterns","title":"设计模式","link":"/topics/patterns/"},{"id":"go","title":"Go","link":"/topics/go/"}],"kind":"设计意图与对象责任","scope":"general","audience":"general","group":"原理与设计","summary":"先判断要转换接口、简化入口、叠加行为、控制访问，还是组合对象结构；再决定是否需要桥接独立维度或共享不可变状态。","status":"active","related":[{"title":"备忘录","link":"/principles/patterns/behavior/memento","kind":"设计意图与对象责任","scope":"general","audience":"general"},{"title":"策略","link":"/principles/patterns/behavior/strategy","kind":"设计意图与对象责任","scope":"general","audience":"general"},{"title":"抽象工厂","link":"/principles/patterns/creation/abstract-factory","kind":"设计意图与对象责任","scope":"general","audience":"general"},{"title":"创建型设计模式","link":"/principles/patterns/creation/patterns-creation-general-general","kind":"设计意图与对象责任","scope":"general","audience":"general"},{"title":"代理","link":"/principles/patterns/structure/proxy","kind":"设计意图与对象责任","scope":"general","audience":"general"}],"prev":{"text":"代理","link":"/principles/patterns/structure/proxy"},"next":{"text":"桥接","link":"/principles/patterns/structure/bridge"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"代理","link":"/principles/patterns/structure/proxy"},"next":{"text":"桥接","link":"/principles/patterns/structure/bridge"}},"headers":[],"relativePath":"principles/patterns/structure/patterns-structure-general-general.md","filePath":"principles/patterns/structure/patterns-structure-general-general.md"}'),s={name:"principles/patterns/structure/patterns-structure-general-general.md"};function p(i,e,d,c,o,l){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="结构型设计模式" tabindex="-1">结构型设计模式 <a class="header-anchor" href="#结构型设计模式" aria-label="Permalink to &quot;结构型设计模式&quot;">​</a></h1><p>本页按场景选择方法；通过各条目链接阅读完整推演、源码和输出。</p><p>各例是独立 main.go，需先创建模块再单独保存当前代码；本轮未执行。接口字段必须先提供有效实现，组合结构须有限无环且子节点非 nil；示例没有统一的空值防护或并发保证。外观中的 Save/Notify 是空实现，仅演示调用顺序，并未实际持久化或通知。</p><table tabindex="0"><thead><tr><th>要解决的问题</th><th>可选方法</th><th>选择前确认</th></tr></thead><tbody><tr><td>复用接口不匹配的旧代码</td><td>适配器</td><td>只负责接口与数据转换；示例保留错误传递，避免混入业务规则。</td></tr><tr><td>把常见的多步子系统调用收成一个入口</td><td>外观</td><td>减少调用方对步骤顺序的了解，同时保留特殊场景所需的底层能力。</td></tr><tr><td>在同一接口上叠加能力或限制访问</td><td>装饰器或代理</td><td>装饰器逐层添加行为且顺序有影响；代理控制转发，权限入口需避免绕过。</td></tr><tr><td>内容与呈现方式需要分别扩展</td><td>桥接</td><td>两个维度用接口连接，边界应对应真正独立变化的能力。</td></tr><tr><td>统一操作单个对象和递归对象树</td><td>组合</td><td>容器递归委托子节点；需定义空组、循环引用与错误传播。</td></tr><tr><td>大量对象重复保存相同配置</td><td>享元</td><td>共享内部状态应不可变；外部状态由各对象保存，并发缓存需同步。</td></tr></tbody></table><h2 id="scene-connect-existing-systems" tabindex="-1">接入旧接口并简化子系统入口 <a class="header-anchor" href="#scene-connect-existing-systems" aria-label="Permalink to &quot;接入旧接口并简化子系统入口 {#scene-connect-existing-systems}&quot;">​</a></h2><h3 id="entry-adapter-14b74b89ff" tabindex="-1">适配器 <a class="header-anchor" href="#entry-adapter-14b74b89ff" aria-label="Permalink to &quot;适配器 {#entry-adapter-14b74b89ff}&quot;">​</a></h3><p><span id="输出"></span><span id="示例"></span></p><p><span id="entry-adapter-14b74b89ff-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/patterns/structure/adapter">适配器</a>。</p><p>适配器应专注接口和数据转换，避免混入业务规则。</p><h3 id="entry-facade-5adaaa2d1b" tabindex="-1">外观 <a class="header-anchor" href="#entry-facade-5adaaa2d1b" aria-label="Permalink to &quot;外观 {#entry-facade-5adaaa2d1b}&quot;">​</a></h3><p><span id="输出-1"></span><span id="示例-1"></span></p><p><span id="entry-facade-5adaaa2d1b-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/patterns/structure/facade">外观</a>。</p><p>外观可以简化常见操作，但应保留必要的底层能力供特殊场景使用。</p><h2 id="scene-wrap-and-control" tabindex="-1">包装现有能力并控制访问 <a class="header-anchor" href="#scene-wrap-and-control" aria-label="Permalink to &quot;包装现有能力并控制访问 {#scene-wrap-and-control}&quot;">​</a></h2><h3 id="entry-decorator-537e6a15fe" tabindex="-1">装饰器 <a class="header-anchor" href="#entry-decorator-537e6a15fe" aria-label="Permalink to &quot;装饰器 {#entry-decorator-537e6a15fe}&quot;">​</a></h3><p><span id="输出-2"></span><span id="示例-2"></span></p><p><span id="entry-decorator-537e6a15fe-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/patterns/structure/decorator">装饰器</a>。</p><p>装饰器适合添加与核心任务正交的行为，但包装层过多会使调试路径变长。</p><h3 id="entry-proxy-6917582c2e" tabindex="-1">代理 <a class="header-anchor" href="#entry-proxy-6917582c2e" aria-label="Permalink to &quot;代理 {#entry-proxy-6917582c2e}&quot;">​</a></h3><p><span id="输出-3"></span><span id="示例-3"></span></p><p><span id="entry-proxy-6917582c2e-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/patterns/structure/proxy">代理</a>。</p><p>同样的结构可用于缓存或延迟创建，但涉及权限时必须确保不存在绕过代理的直接入口。</p><h2 id="scene-separate-dimensions" tabindex="-1">让内容与渲染实现分别变化 <a class="header-anchor" href="#scene-separate-dimensions" aria-label="Permalink to &quot;让内容与渲染实现分别变化 {#scene-separate-dimensions}&quot;">​</a></h2><h3 id="entry-bridge-2281905329" tabindex="-1">桥接 <a class="header-anchor" href="#entry-bridge-2281905329" aria-label="Permalink to &quot;桥接 {#entry-bridge-2281905329}&quot;">​</a></h3><p><span id="输出-4"></span><span id="示例-4"></span></p><p><span id="entry-bridge-2281905329-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/patterns/structure/bridge">桥接</a>。</p><p>接口边界应放在真正会独立变化的能力上。HTML.Render 仅演示组合，直接拼接固定教学文本；真实 HTML 输出含用户输入时必须进行上下文合适的转义，例如文本节点使用 html.EscapeString，或采用 html/template。</p><h2 id="scene-compose-object-trees" tabindex="-1">统一访问单个对象与对象树 <a class="header-anchor" href="#scene-compose-object-trees" aria-label="Permalink to &quot;统一访问单个对象与对象树 {#scene-compose-object-trees}&quot;">​</a></h2><h3 id="entry-composite-6502bdb5bb" tabindex="-1">组合 <a class="header-anchor" href="#entry-composite-6502bdb5bb" aria-label="Permalink to &quot;组合 {#entry-composite-6502bdb5bb}&quot;">​</a></h3><p><span id="输出-5"></span><span id="示例-5"></span></p><p><span id="entry-composite-6502bdb5bb-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/patterns/structure/composite">组合</a>。</p><p>设计递归结构时要决定空组、循环引用和错误传播应如何处理。</p><h2 id="scene-share-immutable-state" tabindex="-1">复用大量对象的不可变配置 <a class="header-anchor" href="#scene-share-immutable-state" aria-label="Permalink to &quot;复用大量对象的不可变配置 {#scene-share-immutable-state}&quot;">​</a></h2><h3 id="entry-flyweight-4d5e9f330b" tabindex="-1">享元 <a class="header-anchor" href="#entry-flyweight-4d5e9f330b" aria-label="Permalink to &quot;享元 {#entry-flyweight-4d5e9f330b}&quot;">​</a></h3><p><span id="输出-6"></span><span id="示例-6"></span></p><p><span id="entry-flyweight-4d5e9f330b-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/patterns/structure/flyweight">享元</a>。</p><p>被共享的 Style 应视为不可变；并发访问缓存时还需要同步保护。</p><h2 id="review-exercise" tabindex="-1">静态自检 <a class="header-anchor" href="#review-exercise" aria-label="Permalink to &quot;静态自检 {#review-exercise}&quot;">​</a></h2><p>将桥接示例 Text 换成字面量 <code>&lt;script&gt;</code> 文本，当前 HTML.Render 会做转义吗？提示：只看 Render 的字符串拼接。</p><details class="details custom-block"><summary>参考解法</summary><p>不会；它只演示接口组合。真实文本节点必须转义或使用 html/template，不能把这个固定字符串例子当作安全 HTML 渲染器。</p></details>',47)])])}const b=t(s,[["render",p]]);export{u as __pageData,b as default};
